function exploreCodeModePaths(params: { question: string }) {
  const files = listFiles();
  const relevantFiles = files.filter(f => 
    f.includes('code') || f.includes('mode') || f.includes('harness') || f.includes('test') || f.includes('exec') || f.includes('run')
  );

  // Search for Code Mode references
  const codeModeRefs = searchText('Code Mode');
  const codeModeLowerRefs = searchText('code mode');
  const codeModeCamelRefs = searchText('codeMode');

  // Search for harness-related files
  const harnessRefs = searchText('harness');

  // Search for execution paths
  const execPathRefs = searchText('execution path');
  const execRefs = searchText('execute');

  return {
    relevantFiles,
    codeModeRefs,
    codeModeLowerRefs,
    codeModeCamelRefs,
    harnessRefs,
    execPathRefs,
    execRefs
  };
}

