() => {
  const files = listFiles();
  const topLevelDirs = files.filter(f => f.includes('/') && !f.startsWith('.') && !f.includes('.git') && !f.includes('.vscode') && !f.includes('.scratch') && !f.includes('.agents') && !f.includes('.vibe'));
  return topLevelDirs.slice(0, 50);
}

() => {
  const files = listFiles();
  const uniqueDirs = new Set();
  files.forEach(f => {
    const parts = f.split('/');
    if (parts.length > 1 && !f.startsWith('.') && !f.includes('.git') && !f.includes('.vscode') && !f.includes('.scratch')) {
      uniqueDirs.add(parts[0]);
    }
  });
  return Array.from(uniqueDirs);
}

