() => {
  const files = listFiles();
  const rootFiles = files.filter(f => !f.includes('/') && !f.startsWith('.'));
  return rootFiles;
}

() => {
  const allFiles = listFiles();
  const rootFiles = allFiles.filter(f => !f.includes('/'));
  const dirs = allFiles.filter(f => f.includes('/')).map(f => f.split('/')[0]);
  const uniqueDirs = [...new Set(dirs)];
  return { rootFiles, uniqueDirs };
}

() => {
